  assert.throws(() => executeVerification({directory: f.directory,
    config: {...config, exclude: ['frontend']}, run: () => {calls++;}}), /Invalid local-only/);
  assert.equal(calls, 0, 'invalid accepted recipe stops before executing any command');
}));

